import{j as e}from"./motion-BJIk69pZ.js";import{C as a}from"./Card-Bd5hMyZz.js";import{B as i}from"./index-BSSsmqaN.js";import{e as n}from"./react-BQIr6j2H.js";import"./charts-BYFiz5UO.js";const r=[{h:"Local data storage",p:"Studifree stores your learning data on your device using IndexedDB and LocalStorage. Your lessons, decks, cards, quizzes and settings are not uploaded to a Studifree server."},{h:"Visitor notifications",p:"When you open the deployed Studifree website, the site may send a visitor notification email through EmailJS. This notification contains the visit time, page URL, your IP address (looked up through ipify), browser user agent, language, screen size, timezone, referrer and platform. It is used only to understand visits to the site. It is not linked to your study data and does not include location unless you separately switch on location in visitor analytics. EmailJS acts as a third-party delivery service for these notifications."},{h:"Location personalisation (optional)",p:"Studifree asks once whether you want location personalisation. No precise location is read from your browser unless you choose “Allow location” and the browser grants permission. When you allow it, your coordinates are used in memory to look up a general country and first-level region. The coordinates are not stored in your browser and are not sent to the AI provider. Only the country and region are saved locally. If you choose “Maybe later” or deny permission, no location is read and Studifree works normally. You can disable or reset this in Settings → Location personalisation, and revoke browser permission in your browser’s site settings."},{h:"Reverse geocoding service",p:"To turn coordinates into a country and region, Studifree sends the coordinates of that one request to BigDataCloud’s public reverse-geocoding service. The coordinates are used only to return the coarse region, are not stored by Studifree, and are not sent to the AI provider. If the lookup fails, only the fact that you allowed location is stored."},{h:"Regional context in AI features",p:"AI features do not receive your location automatically. The AI teacher includes regional context only when you switch on “Use regional context” for that request. When enabled, only the general country and region are added to the prompt, never precise coordinates. The AI is instructed to ignore the region when it is not relevant and not to invent local facts. You can leave the switch off and use every AI feature without sharing any location."},{h:"Location in visitor analytics (separate opt-in)",p:"Visitor analytics is separate from personalisation. In Settings → Location personalisation you can switch on “Location in visitor analytics”, which is off by default. When it is on and location personalisation is allowed, the deployed site may send precise latitude, longitude and accuracy in the same EmailJS visitor notification described above, together with the visit time, page URL and IP address. It is not required for personalisation. You can switch it off at any time; this does not affect learning features."},{h:"API-key handling",p:"If you add an API key, it is stored in your browser. It is sent only to the AI provider you choose when you use AI features. Browser storage is not completely secure against someone with access to your browser profile, so avoid shared devices. You can remove the key at any time in AI Setup. Studifree does not log your key or include it in error messages."},{h:"Third-party AI providers",p:"When you use AI features, your prompts and uploaded content are sent to the selected provider, subject to that provider's terms and privacy policy. Google processes Gemini API requests under your own account and may apply quotas or charges."},{h:"File processing",p:"PDFs and images are processed locally in your browser to extract text. File contents may be sent to your AI provider if you request AI features on them."},{h:"Data deletion",p:"You can delete all local data from Settings. Clearing browser data also removes it. Deleting local data does not delete visitor notification emails already delivered, or records held by third-party providers."},{h:"Export",p:"You can export your study data as JSON from Settings at any time."},{h:"AI limitations",p:"AI output may be inaccurate or inappropriate. You are responsible for verifying content before relying on it."},{h:"User responsibility for uploaded content",p:"You must have the rights to any content you upload."}];function h(){const t=n();return e.jsxs("div",{className:"px-5 pt-6 pb-4 max-w-3xl mx-auto space-y-6",children:[e.jsxs("div",{children:[e.jsx("h1",{className:"text-2xl font-semibold text-ink",children:"Privacy Policy (Draft)"}),e.jsx("p",{className:"text-xs text-faint mt-1",children:"Draft for review by a qualified professional before public launch."})]}),r.map(o=>e.jsxs(a,{children:[e.jsx("h2",{className:"font-semibold text-ink mb-2",children:o.h}),e.jsx("p",{className:"text-muted leading-relaxed",children:o.p})]},o.h)),e.jsxs(a,{children:[e.jsx("h2",{className:"font-semibold text-ink mb-2",children:"Questions about privacy"}),e.jsx("p",{className:"text-sm text-muted mb-3",children:"The FAQ and Help Centre explain how location consent, AI keys and local storage work in practice."}),e.jsxs("div",{className:"flex flex-wrap gap-2",children:[e.jsx(i,{size:"sm",variant:"secondary",onClick:()=>t("/about#faq"),children:"Read the FAQ"}),e.jsx(i,{size:"sm",variant:"secondary",onClick:()=>t("/help"),children:"Open Help Centre"})]})]})]})}export{h as default};
